window.PP_BANKS=window.PP_BANKS||{};window.PP_BANKS["econ-150-ch17"]={"schema":"precise-practice/1","bank_id":"econ-150-ch17","book":"econ-150","chapter":17,"title":"Chapter 17 practice: Externalities","storage_version":1,"status":"prototype","blueprint":"docs/blueprints/econ-150-ch17-18.md","settings":{"goals":{"1":10,"2":5,"3":3}},"concepts":[{"id":"c1","number":1,"name":"What Is an Externality?","activities":[{"id":"c1-quick-sign","type":"quick","tier":1,"title":"Positive or negative?","targets":["17.1a"],"status":"prototype","instructions":"Does the spillover help or hurt the third party?","labels":["Positive externality","Negative externality"],"round_size":8,"items":[{"id":"E17-C1-PN01","prompt":"A neighbor's dog barks all night and keeps you awake.","answer":1,"why":"You bear a cost from someone else's choice, and no one pays you for it.","label_misconceptions":["M17-02",null],"_v":"87c0e1596c"},{"id":"E17-C1-PN02","prompt":"A beekeeper's bees pollinate the orchard next door.","answer":0,"why":"The orchard gets a benefit it didn't pay for.","label_misconceptions":[null,"M17-02"],"_v":"fd1b0c11a5"},{"id":"E17-C1-PN03","prompt":"Smoke from a factory dirties laundry hanging in nearby yards.","answer":1,"why":"The families nearby bear a cost they never agreed to.","label_misconceptions":["M17-02",null],"_v":"f4761b0b0c"},{"id":"E17-C1-PN04","prompt":"You get a measles shot, and your baby cousin becomes less likely to catch measles.","answer":0,"why":"Your cousin gets protection without paying for it.","label_misconceptions":[null,"M17-02"],"_v":"bed0c2e414"},{"id":"E17-C1-PN05","prompt":"A family restores a run-down historic house, and home values on the street go up.","answer":0,"why":"The neighbors gain value from a choice they didn't pay for.","label_misconceptions":[null,"M17-02"],"_v":"94a4bb18dd"},{"id":"E17-C1-PN06","prompt":"One more driver joins rush-hour traffic and slows everyone else down.","answer":1,"why":"Every other driver loses a little time, and the new driver doesn't pay for it.","label_misconceptions":["M17-02",null],"_v":"86eed1a02e"},{"id":"E17-C1-PN07","prompt":"A company trains its workers in a skill they later use at other firms.","answer":0,"why":"The other firms gain trained workers they didn't pay to train.","label_misconceptions":[null,"M17-02"],"_v":"48e534b0f1"},{"id":"E17-C1-PN08","prompt":"Late-night fireworks wake up the whole neighborhood.","answer":1,"why":"The neighbors lose sleep, and the person setting off fireworks doesn't pay for it.","label_misconceptions":["M17-02",null],"_v":"43981963d8"}]},{"id":"c1-quick-side","type":"quick","tier":1,"title":"Production or consumption?","targets":["17.1b"],"status":"prototype","instructions":"Does the spillover come from making a good or from using one?","labels":["Production externality","Consumption externality"],"round_size":8,"items":[{"id":"E17-C1-PC01","prompt":"A paper mill's wastewater kills fish downstream.","answer":0,"why":"The harm comes from making paper.","label_misconceptions":[null,"M17-03"],"_v":"e3ca47f89b"},{"id":"E17-C1-PC02","prompt":"Someone smokes at a crowded bus stop.","answer":1,"why":"The harm comes from using a cigarette, not from making it.","label_misconceptions":["M17-03",null],"_v":"13052fdb31"},{"id":"E17-C1-PC03","prompt":"Bees from a honey farm pollinate a neighbor's orchard.","answer":0,"why":"The benefit comes from producing honey.","label_misconceptions":[null,"M17-03"],"_v":"109b839cb5"},{"id":"E17-C1-PC04","prompt":"A student gets a flu shot, and her roommates are less likely to get sick.","answer":1,"why":"The benefit comes from using the vaccine.","label_misconceptions":["M17-03",null],"_v":"6466014bf5"},{"id":"E17-C1-PC05","prompt":"A data center's cooling fans hum all night next to a neighborhood.","answer":0,"why":"The noise comes from producing computing services.","label_misconceptions":[null,"M17-03"],"_v":"5751c9d922"},{"id":"E17-C1-PC06","prompt":"A commuter's car adds to the city's smog.","answer":1,"why":"The pollution comes from using a car, so it is a consumption externality.","label_misconceptions":["M17-03",null],"_v":"fc8a67df6b"},{"id":"E17-C1-PC07","prompt":"A tech firm's research produces ideas that other firms copy for free.","answer":0,"why":"The benefit comes from the firm's production of new knowledge.","label_misconceptions":[null,"M17-03"],"_v":"130dfc3dc5"},{"id":"E17-C1-PC08","prompt":"A homeowner throws a loud party that keeps the street awake.","answer":1,"why":"The noise comes from enjoying the party, not from making anything for sale.","label_misconceptions":["M17-03",null],"_v":"b7b67d3fe4"}]},{"id":"c1-sort-four","type":"sort","tier":1,"title":"Both questions at once","targets":["17.1a","17.1b"],"status":"prototype","instructions":"Sort each case by both questions: helps or hurts, and making or using.","bins":["Negative, production","Negative, consumption","Positive, production","Positive, consumption"],"round_size":4,"cards":[{"id":"E17-C1-FS01","text":"Dust from a cement plant coats cars in the next neighborhood.","bin":0,"why":"It hurts others, and it comes from making cement.","bin_misconceptions":[null,"M17-03","M17-02","M17-02"],"_v":"201da5c7ff"},{"id":"E17-C1-FS02","text":"A car stereo blasts at a stoplight.","bin":1,"why":"It hurts others, and it comes from using a good.","bin_misconceptions":["M17-03",null,"M17-02","M17-02"],"_v":"9d8f2f9c3c"},{"id":"E17-C1-FS03","text":"An apple orchard's blossoms feed a neighbor's bees.","bin":2,"why":"It helps others, and it comes from growing apples.","bin_misconceptions":["M17-02","M17-02",null,"M17-03"],"_v":"96b88799ff"},{"id":"E17-C1-FS04","text":"A homeowner plants a flower garden the whole street enjoys.","bin":3,"why":"It helps others, and it comes from the homeowner using the yard.","bin_misconceptions":["M17-02","M17-02","M17-03",null],"_v":"65235a22fa"},{"id":"E17-C1-FS05","text":"A hog farm's smell drifts over a new subdivision.","bin":0,"why":"It hurts others, and it comes from raising hogs.","bin_misconceptions":[null,"M17-03","M17-02","M17-02"],"_v":"636c02caa0"},{"id":"E17-C1-FS06","text":"Picnickers leave trash behind in a public park.","bin":1,"why":"It hurts others, and it comes from using the park and the picnic food.","bin_misconceptions":["M17-03",null,"M17-02","M17-02"],"_v":"7d9013ecc8"},{"id":"E17-C1-FS07","text":"A drug company's research teaches other labs a new method.","bin":2,"why":"It helps others, and it comes from producing research.","bin_misconceptions":["M17-02","M17-02",null,"M17-03"],"_v":"b0e5bc943a"},{"id":"E17-C1-FS08","text":"A worker gets a flu shot, and her coworkers stay healthier.","bin":3,"why":"It helps others, and it comes from using the vaccine.","bin_misconceptions":["M17-02","M17-02","M17-03",null],"_v":"2b5e6cdce7"}]},{"id":"c1-detective","type":"detective","tier":1,"title":"Definition Detective","targets":["17.1a"],"status":"prototype","rounds":[{"id":"E17-C1-DD01","term":"Externality","answers":[{"text":"A cost or benefit from a deal that falls on someone outside the deal, who never agreed to it.","grade":"A","why":"It names both parts: a third party, and no say in the deal."},{"text":"A side effect of buying or selling something.","grade":"A-","why":"Close, but it leaves out who bears it. The side effect has to land on someone outside the deal."},{"text":"A cost the buyer pays that wasn't in the posted price, like a hidden fee.","grade":"F","why":"A hidden fee lands on the buyer, who is inside the deal. An externality lands on a third party.","misconception":"M17-01"}],"_v":"cf8ede142d"}]}]},{"id":"c2","number":2,"name":"Private and Social Cost","activities":[{"id":"c2-quick-side","type":"quick","tier":1,"title":"Which side of the graph?","targets":["17.2a"],"status":"prototype","instructions":"Production externalities change the cost side. Consumption externalities change the benefit side.","labels":["Cost side: MSC ≠ MPC","Benefit side: MSB ≠ MPB"],"round_size":4,"items":[{"id":"E17-C2-WS01","prompt":"A refinery's fumes make nearby residents sick.","answer":0,"why":"The harm comes from production, so social cost is above private cost.","label_misconceptions":[null,"M17-04"],"_v":"29df89985f"},{"id":"E17-C2-WS02","prompt":"Students who get vaccinated protect their classmates.","answer":1,"why":"The benefit comes from using the vaccine, so social benefit is above private benefit.","label_misconceptions":["M17-04",null],"_v":"94d6d0b0a9"},{"id":"E17-C2-WS03","prompt":"A bakery's ovens make the whole block smell wonderful.","answer":0,"why":"The benefit comes from production, so the social cost of baking is a little below the private cost.","label_misconceptions":[null,"M17-04"],"_v":"41ac1740c8"},{"id":"E17-C2-WS04","prompt":"People playing music on a crowded beach bother everyone nearby.","answer":1,"why":"The harm comes from using a good, so social benefit is below private benefit.","label_misconceptions":["M17-04",null],"_v":"9a958bc938"}]},{"id":"c2-repair","type":"choice","tier":2,"title":"Repair the reasoning","targets":["17.2b"],"status":"prototype","instructions":"Pick the best fix for the student's reasoning.","items":[{"id":"E17-C2-RR01","prompt":"A student writes: “Pollution is a negative externality, so the efficient amount of pollution is zero.” Which correction is best?","options":["The efficient amount is where the benefit of one more unit of the activity equals its full social cost, which is usually above zero.","The student is right; any pollution means the market has failed.","The efficient amount is whatever the market produces, since buyers and sellers both agreed.","The efficient amount is zero only for production externalities, not consumption ones."],"answer":0,"why":"Getting to zero would mean giving up activities worth far more than the harm they do. The goal is to count the harm, not to erase every bit of it.","option_misconceptions":[null,"M17-05","M17-01","M17-03"],"_v":"ab0a496005"}]}]},{"id":"c3","number":3,"name":"The Negative Externality Graph","activities":[{"id":"c3-graph","type":"choice","tier":2,"title":"Read the graph","targets":["17.3a","17.5a"],"status":"prototype","generated_by":"tools/build_ch17_18_calc.py","instructions":"Read the graph, then choose.","items":[{"id":"E17-C3-GR01","prompt":"Fertilizer runoff from farms harms fishing towns downstream. S1 is the private cost of making fertilizer; S2 adds the harm downstream. Which area is the deadweight loss?","figure":{"kind":"graph","alt":"Fertilizer market. Demand D meets private cost S1 at 70 tons and $45. Demand meets social cost S2, which is $30 higher, at 40 tons and $60. Area A is the triangle between S2 and D from 40 to 70 tons. Area B lies between S1 and S2 from 0 to 40 tons. Area C lies between S1 and D beyond 70 tons, where nothing is produced.","x":{"label":"Tons of fertilizer","max":110},"y":{"label":"Price ($)","max":95},"lines":[{"points":[[0,80.0],[110,25.0]],"label":"D","role":"demand"},{"points":[[0,10.0],[110,65.0]],"label":"S1","role":"supply"},{"points":[[0,40.0],[105,92.5]],"label":"S2","role":"tax"}],"areas":[{"polygon":[[40.0,60.0],[70.0,75.0],[70.0,45.0]],"label":"A","role":"neutral"},{"polygon":[[0,10.0],[40.0,30.0],[40.0,60.0],[0,40.0]],"label":"B","role":"neutral"},{"polygon":[[70.0,45.0],[100,60.0],[100,30.0]],"label":"C","role":"neutral"}],"guides":[{"at":[40.0,60.0],"x_label":"40","y_label":"$60"},{"at":[70.0,45.0],"x_label":"70","y_label":"$45"}],"points":[{"at":[40.0,60.0]},{"at":[70.0,45.0]}]},"options":["Area A","Area B","Area C","Areas A and B together"],"answer":0,"why":"The deadweight loss is the triangle for the units between the efficient quantity (40) and the market quantity (70), where the social cost (S2) is above what buyers value (D). Area B is harm from the first 40 tons, which are worth making anyway. Area C is past the market quantity, where nothing is made.","option_misconceptions":[null,"M17-06","M17-12","M17-06"],"_v":"e54094a549"}]}]},{"id":"c4","number":4,"name":"Positive Externalities","activities":[{"id":"c4-graph","type":"choice","tier":2,"title":"Read the graph","targets":["17.4a","17.5a"],"status":"prototype","generated_by":"tools/build_ch17_18_calc.py","instructions":"Read the graph, then choose.","items":[{"id":"E17-C4-GR01","prompt":"Trees in front yards shade sidewalks and cool the whole street. D1 is private demand; D2 adds the benefit to neighbors. How big is the shaded deadweight loss?","figure":{"kind":"graph","alt":"Front-yard tree planting. Private demand D1 meets supply S at 250 trees and $35. Social benefit D2, which is $15 higher, meets supply at 325 trees and $42.50. The shaded triangle runs from 250 to 325 trees, from $35 up to $50 at 250 trees.","x":{"label":"Trees planted","max":500},"y":{"label":"Price ($)","max":80},"lines":[{"points":[[0,60.0],[500,10.0]],"label":"D1","role":"demand","style":"dotted"},{"points":[[0,75.0],[500,25.0]],"label":"D2","role":"demand"},{"points":[[0,10.0],[500,60.0]],"label":"S","role":"supply"}],"areas":[{"polygon":[[250.0,50.0],[325.0,42.5],[250.0,35.0]],"role":"dwl"}],"guides":[{"at":[250.0,35.0],"x_label":"250","y_label":"$35"},{"at":[325.0,42.5],"x_label":"325"},{"at":[250.0,50.0],"y_label":"$50"}],"points":[{"at":[250.0,35.0]},{"at":[325.0,42.5]}]},"options":["$562.50","$1,125","$1,875","$281.25"],"answer":0,"why":"Height: the external benefit per tree, $50 − $35 = $15. Base: 325 − 250 = 75 trees. DWL = ½ × $15 × 75 = $562.50.","option_misconceptions":[null,"M17-07","M17-08",null],"_v":"6b8af05547"}]},{"id":"c4-ap","type":"choice","tier":3,"title":"Quiz-style questions","targets":["17.4a"],"status":"prototype","items":[{"id":"E17-C4-AP01","prompt":"In a market with a positive externality, compared with the efficient outcome, the market produces","options":["less than the efficient quantity, because buyers don't count the benefit to others","more than the efficient quantity, because the good is valuable","the efficient quantity, because buyers and sellers both gain","less than the efficient quantity, because sellers don't count the cost to others"],"answer":0,"why":"Buyers follow private benefit (D1), which is below social benefit (D2), so the market stops short of the efficient quantity.","option_misconceptions":[null,"M17-11","M17-01","M17-04"],"_v":"46de92a0ef"}]}]},{"id":"c5","number":5,"name":"Measuring Deadweight Loss","activities":[{"id":"c5-calc-dwl","type":"calc","tier":2,"title":"Measure the deadweight loss","targets":["17.5a"],"status":"prototype","generated_by":"tools/build_ch17_18_calc.py","deck":{"id":"dwl-externality","title":"Measure the deadweight loss","skill":"Multiply half the external cost or benefit per unit by the gap between the market and efficient quantities, then say whether the market makes too much or too little.","targets":["17.5a"],"formula":"DWL = ½ × (external cost or benefit per unit) × |Qm − Qs|","hint":"Height is the gap between the private and social curves. Base is only the units the market gets wrong.","worked_example":{"prompt":"Paper mills: the river damage is $20 a ton, the market makes 80 tons, and the efficient amount is 60.","steps":["Height: $20.","Base: 80 − 60 = 20 tons.","DWL = ½ × $20 × 20 = $200 a day. The market makes too much."],"answer":"$200; too much is made"},"rounding_rule":"Give the answer in whole dollars.","progression":[1,1,1],"problems":[{"id":"econ-150.ch17.calc.dwl.p01","prompt":"Plastic packaging: each unit does $4 of harm to others. The market sells 900 units, and the efficient quantity is 700. Find the deadweight loss.","givens":{"external_per_unit":4,"market_quantity":900,"efficient_quantity":700},"answer":{"value":400.0,"tolerance":0.5,"decimals":0,"unit":"dollars"},"classify":{"answer":"too much is made","options":["too much is made","too little is made"]},"solution":["Height: the external cost per unit, $4.","Base: the gap between the two quantities, 900 − 700 = 200.","DWL = ½ × $4 × 200 = $400."],"common_errors":[{"value":800,"tolerance":0.5,"label":"forgot the ½","misconception":"M17-07","feedback":"That's a rectangle. The deadweight loss is a triangle, so take half."},{"value":1800.0,"tolerance":0.5,"label":"used the whole market quantity","misconception":"M17-08","feedback":"The base is only the units the market gets wrong: the gap between the market quantity and the efficient quantity."},{"value":3600,"tolerance":0.5,"label":"total external effect","misconception":"M17-06","feedback":"That's the external cost or benefit on every unit sold. Most of those units are worth making. The deadweight loss is only the triangle between the two quantities."}],"targets":["17.5a"],"misconceptions":[],"review_status":"prototype","_v":"59a6ebab2c"},{"id":"econ-150.ch17.calc.dwl.p02","prompt":"A coding camp: each graduate gives $50 of benefit to employers and coworkers who don't pay for it. The market trains 120 students, and the efficient number is 160. Find the deadweight loss.","givens":{"external_per_unit":50,"market_quantity":120,"efficient_quantity":160},"answer":{"value":1000.0,"tolerance":0.5,"decimals":0,"unit":"dollars"},"classify":{"answer":"too little is made","options":["too much is made","too little is made"]},"solution":["Height: the external benefit per unit, $50.","Base: the gap between the two quantities, 160 − 120 = 40.","DWL = ½ × $50 × 40 = $1,000."],"common_errors":[{"value":2000,"tolerance":0.5,"label":"forgot the ½","misconception":"M17-07","feedback":"That's a rectangle. The deadweight loss is a triangle, so take half."},{"value":3000.0,"tolerance":0.5,"label":"used the whole market quantity","misconception":"M17-08","feedback":"The base is only the units the market gets wrong: the gap between the market quantity and the efficient quantity."},{"value":6000,"tolerance":0.5,"label":"total external effect","misconception":"M17-06","feedback":"That's the external cost or benefit on every unit sold. Most of those units are worth making. The deadweight loss is only the triangle between the two quantities."}],"targets":["17.5a"],"misconceptions":[],"review_status":"prototype","_v":"6c23cb83d2"},{"id":"econ-150.ch17.calc.dwl.p03","prompt":"Leaf blowers: each hour of use does $6 of noise harm to neighbors. People use them 1,500 hours a week, and the efficient amount is 1,100. Find the deadweight loss.","givens":{"external_per_unit":6,"market_quantity":1500,"efficient_quantity":1100},"answer":{"value":1200.0,"tolerance":0.5,"decimals":0,"unit":"dollars"},"classify":{"answer":"too much is made","options":["too much is made","too little is made"]},"solution":["Height: the external cost per unit, $6.","Base: the gap between the two quantities, 1500 − 1100 = 400.","DWL = ½ × $6 × 400 = $1,200."],"common_errors":[{"value":2400,"tolerance":0.5,"label":"forgot the ½","misconception":"M17-07","feedback":"That's a rectangle. The deadweight loss is a triangle, so take half."},{"value":4500.0,"tolerance":0.5,"label":"used the whole market quantity","misconception":"M17-08","feedback":"The base is only the units the market gets wrong: the gap between the market quantity and the efficient quantity."},{"value":9000,"tolerance":0.5,"label":"total external effect","misconception":"M17-06","feedback":"That's the external cost or benefit on every unit sold. Most of those units are worth making. The deadweight loss is only the triangle between the two quantities."}],"targets":["17.5a"],"misconceptions":[],"review_status":"prototype","_v":"e8f424c742"}]}},{"id":"c5-story","type":"choice","tier":2,"title":"What does the triangle mean?","targets":["17.5b"],"status":"prototype","items":[{"id":"E17-C5-ST01","prompt":"In a market for gas-powered leaf blowers, the deadweight loss is $1,200 a week. Which sentence best explains what that number means?","options":["Blower use beyond the efficient amount does $1,200 more harm to neighbors than it's worth to the people using the blowers.","Neighbors suffer $1,200 a week in total noise harm.","The government should collect $1,200 a week in taxes from blower owners.","Blower owners lose $1,200 a week because blowers are overpriced."],"answer":0,"why":"Deadweight loss is the value lost on the extra hours the market gets wrong. Total harm is bigger, because hours worth their full cost also make noise.","option_misconceptions":[null,"M17-06","M17-09",null],"_v":"9c3c85cf82"}]}]},{"id":"c6","number":6,"name":"When a Tax Removes Deadweight Loss","activities":[{"id":"c6-sort","type":"sort","tier":1,"title":"Remove it, create it, or make it worse?","targets":["17.6a"],"status":"prototype","instructions":"What does each policy do to deadweight loss?","bins":["Removes the deadweight loss","Creates a new deadweight loss","Makes the existing deadweight loss bigger"],"round_size":3,"cards":[{"id":"E17-C6-SR01","text":"A tax equal to the harm each unit does, in a market with a negative externality.","bin":0,"why":"The tax makes sellers count the harm, so output falls to the efficient quantity.","bin_misconceptions":[null,"M17-09",null],"_v":"832985179c"},{"id":"E17-C6-SR02","text":"A tax on a good with no externality.","bin":1,"why":"The market was already at the efficient quantity, so the tax pushes output too low (Chapter 7).","bin_misconceptions":["M17-09",null,null],"_v":"6731c2a78b"},{"id":"E17-C6-SR03","text":"A subsidy for a good with a negative externality.","bin":2,"why":"The market already makes too much. A subsidy pushes output even further past the efficient quantity.","bin_misconceptions":["M17-09",null,null],"_v":"3e422d8a02"},{"id":"E17-C6-SR04","text":"A subsidy equal to the benefit each unit gives others, in a market with a positive externality.","bin":0,"why":"The subsidy makes up for the missing benefit, so output rises to the efficient quantity.","bin_misconceptions":[null,"M17-09",null],"_v":"40010cbeff"},{"id":"E17-C6-SR05","text":"A subsidy for a good with no externality.","bin":1,"why":"Output rises past the efficient quantity, paying for units that aren't worth their cost.","bin_misconceptions":["M17-09",null,null],"_v":"793588853b"},{"id":"E17-C6-SR06","text":"A tax on a good with a positive externality.","bin":2,"why":"The market already makes too little. A tax pushes output even lower.","bin_misconceptions":["M17-09",null,null],"_v":"c96c571679"}]}]},{"id":"c7","number":7,"name":"Coase, Bargaining, and Transaction Costs","activities":[{"id":"c7-applied","type":"choice","tier":2,"title":"Who pays, and what happens?","targets":["17.7a"],"status":"prototype","items":[{"id":"E17-C7-AC01","prompt":"A rancher's cattle trample a neighbor's crops. Keeping the cattle out with a fence costs the rancher $300. The trampled crops are worth $800. Bargaining is cheap. If the rancher has the legal right to let cattle roam, what happens?","options":["The farmer pays the rancher between $300 and $800 to build the fence, and the fence goes up.","Nothing changes, because the rancher has the right.","The rancher builds the fence and the farmer pays nothing.","The fence goes up only if a court orders it."],"answer":0,"why":"The fence creates $500 of net value, so there's room for a deal. With the right on the rancher's side, the farmer pays. If the farmer held the right, the rancher would build the fence at his own cost. Either way, the fence goes up.","option_misconceptions":[null,"M17-10","M17-10","M17-10"],"_v":"db0f5d710a"}]}]}],"readiness":{"streak":2,"items":[{"id":"E17-RD01","prompt":"Which is a negative consumption externality?","options":["Cigarette smoke at a crowded bus stop","Wastewater from a paper mill","Bees from a honey farm pollinating an orchard","A flu shot that protects coworkers"],"answer":0,"why":"Smoking is using a good, and it harms people nearby.","option_misconceptions":[null,"M17-03","M17-02","M17-02"],"_v":"82348949bb"},{"id":"E17-RD02","prompt":"On a graph of a negative production externality, the vertical gap between S2 (social cost) and S1 (private cost) measures","options":["the marginal external cost of each unit","the deadweight loss","the tax the government collects","the consumer surplus lost"],"answer":0,"why":"S2 − S1 is the harm one more unit does to people outside the deal.","option_misconceptions":[null,"M17-06","M17-09",null],"_v":"e0b0d79e4f"}],"spiral":[]},"version":"98e533b5f9"};
